import React, { useState } from 'react';
import { NumberInput, IconButton } from '@salutejs/sdds-finai';
import { IconVolumeLevel1Fill, IconVolumeLevel2Fill } from '@salutejs/plasma-icons';
export function App() {
    const [value, setValue] = useState(0);
    const min = 0;
    const max = 10;
    const step = 2;
    return (
        <div>
            <NumberInput
                value={value}
                step={step}
                size="l"
                width={188}
                customDecrementButton={
                    <IconButton
                        size="l"
                        view={value <= min ? 'critical' : 'accent'}
                        disabled={value <= min}
                        onClick={() => setValue(Math.max(min, value - step))}
                    >
                        <IconVolumeLevel1Fill color="inherit" />
                    </IconButton>
                }
                customIncrementButton={
                    <IconButton
                        size="l"
                        view={value >= max ? 'critical' : 'accent'}
                        disabled={value >= max}
                        onClick={() => setValue(Math.min(max, value + step))}
                    >
                        <IconVolumeLevel2Fill color="inherit" />
                    </IconButton>
                }
            />
        </div>
    );
}

